    private function initAreas(): void
    {
        Area::query()->truncate();

        // 首先尝试从 JSON 文件重新初始化
        $jsonPath = base_path('database/seeders/data/areas.json');
        if (file_exists($jsonPath)) {

            $json = file_get_contents($jsonPath);
            $data = json_decode($json, true);

            $columns = Schema::getColumnListing('areas');
            $hasCreatedAt = in_array('created_at', $columns, true);
            $hasUpdatedAt = in_array('updated_at', $columns, true);

            $chunkSize = 500;

            foreach (array_chunk($data, $chunkSize) as $chunk) {
                $batch = [];
                foreach ($chunk as $row) {
                    if (!is_array($row)) {
                        continue;
                    }
                    // 只保留 areas 表存在的列
                    $filtered = array_intersect_key($row, array_flip($columns));

                    // 如果没有 created_at/updated_at，填充当前时间
                    $now = now();
                    if ($hasCreatedAt && empty($filtered['created_at'])) {
                        $filtered['created_at'] = $now;
                    }
                    if ($hasUpdatedAt && empty($filtered['updated_at'])) {
                        $filtered['updated_at'] = $now;
                    }

                    $batch[] = $filtered;
                }

                if (!empty($batch)) {
                    DB::table('areas')->insert($batch);
                }
            }
        }
    }

    private function initSchools(): void
    {

        School::query()->truncate();

        $data = $this->getFullSchoolData(Carbon::now());

        foreach (array_chunk($data, 500) as $chunk) {
            foreach ($chunk as $item) {
                try {
                    if (School::query()->where('school_code', $item['school_code'])->orWhere('name', $item['name'])->exists()) {
                        continue;
                    }
                    School::query()->create($item);
                } catch (Exception $e) {
                    dd($item);

                    continue;
                }
            }
        }
    }

